const line=pts=>pts.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(4)} ${y.toFixed(4)}`).join(' ');
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={select:'m5 3 13 9-7 1-3 7Z',curve:'M3 17C7 17 6 6 12 6s5 10 9 3M3 14v6m-3-3h6M12 3v6m-3-3h6M21 6v6m-3-3h6',measure:'m3 16 13-13 5 5L8 21Zm5-5 3 3m1-7 3 3m1-7 3 3',pan:'M8 11V5a2 2 0 0 1 4 0v6-8a2 2 0 0 1 4 0v8-5a2 2 0 0 1 4 0v9l-3 6H9l-6-8a2 2 0 0 1 3-2l2 2',save:'M4 3h13l4 4v14H3V3Zm3 0v7h10V3M7 21v-8h10v8',open:'M3 7V4h7l2 3h9l-3 13H3V7Z',undo:'M8 5 3 10l5 5M3 10h11a6 6 0 0 1 0 12',redo:'m16 5 5 5-5 5m5-5H10a6 6 0 0 0 0 12',fit:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6M8 8h8v8H8Z',grid:'M3 3h18v18H3Zm6 0v18m6-18v18M3 9h18M3 15h18',wire:'m12 2 10 5v10l-10 5-10-5V7Zm0 0v20M2 7l10 5 10-5',print:'M6 8V2h12v6M6 18H2V8h20v10h-4M6 14h12v8H6Zm11-3h2',box:'m12 2 10 5v10l-10 5-10-5V7Zm0 10v10M2 7l10 5 10-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',plus:'M12 4v16M4 12h16',minus:'M4 12h16',reset:'M4 10a8 8 0 1 1 1 8M4 3v7h7',top:'M4 5h16v14H4ZM4 9h16',quad:'M3 3h18v18H3Zm9 0v18M3 12h18',download:'M12 2v13m-5-5 5 5 5-5M3 16v6h18v-6'};
