export function planSVG(design,options={}){
 const {view='front',handles=true,layers={},dimensions=true}=options,m=designMeasurements(design),centers=lensCenters(design),on=key=>layers[key]!==false;
 let geometry='',viewBox='-100 -66 200 132';
 if(view==='front'){
  for(const [i,side] of [-1,1].entries()){
   const project=([x,y])=>[(x+centers[i])/MM,-y/MM],outer=frameContour(design,side).map(project),inner=lensContour(design,side).map(project);
   if(on('lenses'))geometry+=`<path data-part="lenses" class="cad-plan-lens" d="${pth(inner)}"/>`;
   if(on('rims')&&!on('bridge'))geometry+=`<path data-part="rims" class="plan-rim" fill-rule="evenodd" d="${pth(outer)} ${pth(inner)}"/>`;
  }
  if(on('rims')&&on('bridge')){const cut=frontCutGeometry(design);geometry+=`<path data-part="rims" class="plan-rim" fill-rule="evenodd" d="${[...cut.outerLoops,...cut.holes].map(loop=>pth(loop.map(([x,y])=>[x,-y]))).join(' ')}"/>`;}else if(on('bridge'))geometry+=bridgeGeometry(design).bands.map(b=>`<path data-part="bridge" class="plan-rim" d="${pth(b.outline.map(([x,y])=>[x/MM,-y/MM]))}"/>`).join('');
  if(dimensions&&on('guides')){for(const side of [-1,1]){const h=hingeGeometry(design,side);geometry+=`<rect class="cad-hinge-guide" x="${h.anchor[0]/MM-1}" y="${-h.anchor[1]/MM-1.5}" width="2" height="3"/>`;if(on('pads'))geometry+=`<path class="cad-pad-guide" d="${pth(nasalPads(design,side).outline.map(([x,y])=>[x/MM,-y/MM]))}"/>`;}}if(dimensions&&on('guides'))geometry+=`<g class="cad-dimensions"><path d="M${-m.front/2} 39V47M${m.front/2} 39V47M${-m.front/2} 44H${m.front/2}"/><text x="0" y="50" text-anchor="middle">${Number(m.front).toFixed(1)} mm · frontal</text><text x="0" y="-43" text-anchor="middle">A ${m.lens} · B ${m.lensHeight} · DBL ${m.bridge}</text></g>`;
  if(dimensions&&on('guides')){const bg=bridgeGeometry(design).bands.flatMap(b=>b.outline),xs=bg.map(p=>p[0]/MM),ys=bg.map(p=>-p[1]/MM);geometry+=`<rect class="cad-bridge-box" x="${Math.min(...xs)}" y="${Math.min(...ys)}" width="${Math.max(...xs)-Math.min(...xs)}" height="${Math.max(...ys)-Math.min(...ys)}"/>`;}if(handles&&on('rims')){
   const contour=frameContour(design,1),center=centers[1]/MM;
   const temporal=contour.reduce((a,p)=>p[0]+p[1]>a[0]+a[1]?p:a,contour[0]),nasal=contour.reduce((a,p)=>-p[0]-p[1]>.99*(-a[0]-a[1])?p:a,contour[0]);
   const grips=[['temporalLift',center+temporal[0]/MM,-temporal[1]/MM,'Altura temporal',design.temporalLift??0,0,12],['temporalReach',center+Math.max(...contour.map(p=>p[0]))/MM,0,'Extensión temporal',design.temporalReach??0,0,8],['nasalAngle',center+nasal[0]/MM,-nasal[1]/MM,'Apertura nasal',design.nasalAngle??0,0,15]];
   geometry+=`<g class="cad-curve-handles">${grips.map(([key,x,y,label,value,min,max])=>`<circle class="plan-grip" data-grip="${key}" cx="${x}" cy="${y}" r="1.5" tabindex="0" role="slider" aria-label="${label}" aria-valuemin="${min}" aria-valuemax="${max}" aria-valuenow="${value}"/><text x="${x+3}" y="${y-3}">${label}</text>`).join('')}</g>`;
  }
  if(handles&&on('rims')&&design.customContour){const points=normalizeContour(design.customContour),ys=points.map(p=>p[1]),height=Math.max(...ys)-Math.min(...ys),a=m.nominalLens/2,b=m.nominalLensHeight/height;geometry+=`<g class="cad-curve-handles cad-profile-nodes">${contourControlIndices(points).map((index,number)=>{const p=points[index],x=centers[1]/MM+p[0]*a,y=-p[1]*b;return `<circle data-contour-node="${index}" cx="${x}" cy="${y}" r="1.2" tabindex="0" role="slider" aria-label="Nodo de perfil ${number+1}" aria-valuemin="-2.5" aria-valuemax="2.5" aria-valuenow="0"/><text x="${x+2}" y="${y-2}">${number+1}</text>`;}).join('')}</g>`;}
 }else{
  const top=view==='top',rows=[-1,1].map(side=>templeSections(design,side)),project=p=>top?[p[0]/MM,-p[2]/MM]:[-p[2]/MM,-p[1]/MM];viewBox=top?'-100 -20 200 190':'-15 -62 180 115';
  if(on('rims')){
   if(top){const outer=frameContour(design,1),xs=[-1,1].flatMap((side,i)=>frameContour(design,side).map(([x])=>(x+centers[i])/MM)),left=Math.min(...xs),right=Math.max(...xs);geometry+=`<rect data-part="rims" class="plan-rim" x="${left}" y="${-(design.materialDepth||6)}" width="${right-left}" height="${design.materialDepth||6}"/>`;}
   else{const contour=frameContour(design,1),ys=contour.map(p=>-p[1]/MM);geometry+=`<rect data-part="rims" class="plan-rim" x="${-(design.materialDepth||6)}" y="${Math.min(...ys)}" width="${design.materialDepth||6}" height="${Math.max(...ys)-Math.min(...ys)}"/>`;}
  }
  if(on('temples'))for(const sections of top?rows:[rows[1]]){
   const points=[...sections.stem,...sections.hook.slice(1)];
   const high=points.map(row=>{const p=project(row.point);return [p[0]+(top?row.depth/MM:0),p[1]-(top?0:row.height/MM/2)];});
   const low=points.map(row=>{const p=project(row.point);return [p[0]-(top?row.depth/MM:0),p[1]+(top?0:row.height/MM/2)];});
   geometry+=`<path data-part="temples" class="cad-plan-temple" d="${pth([...high,...low.reverse()])}"/>`;
  }
  if(dimensions&&on('guides'))geometry+=`<text class="cad-projection-note" x="${top?0:65}" y="${top?164:46}" text-anchor="middle">${top?'Superior · X / Z':'Lateral · Z / Y'} · L ${m.temple} mm</text>`;
 }
 return `<svg viewBox="${viewBox}" data-plane="${view}" role="img" aria-label="${view==='front'?'Plano frontal acotado':view==='top'?'Proyección superior':'Proyección lateral'} en milímetros"><defs><pattern id="cad-grid-${view}" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M5 0H0V5" fill="none" stroke="#dbe2e8" stroke-width=".12"/></pattern></defs>${on('guides')?`<rect x="-500" y="-500" width="1000" height="1000" fill="url(#cad-grid-${view})"/><path class="cad-axis" d="M-500 0H500M0-500V500"/>`:''}${geometry}</svg>`;
}

