 const importSection=document.createElement('section');importSection.className='cad-reference-import';importSection.innerHTML=`<label class="cad-import-drop">${icon('open')}<strong>Foto o boceto</strong><span>Detectar el perfil automáticamente</span><input id="studio-extract-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p id="studio-extract-status" role="status">Frontal · fondo claro · dos aberturas cerradas.</p><div id="studio-extract-preview"></div><div class="cad-reference-scale"><label for="studio-reference-scale">Ancho A conocido · mm<input id="studio-reference-scale" type="number" min="40" max="65" step="0.1" value="50" required></label><p id="studio-reference-resolution"></p></div><button type="button" id="studio-apply-reference" disabled>Calibrar y aplicar modelo</button>`;q('#cad-reference-slot').append(importSection);
